import heapq
from itertools import count


def shortest_path(edges, start, end):
    """
    Return (shortest_distance, path), where path is a list of nodes.

    Returns (None, None) if no route exists.
    Raises ValueError if any edge has a negative weight.
    """
    graph = {}

    # Validate edges and build the adjacency list
    for from_node, to_node, weight in edges:
        if weight < 0:
            raise ValueError("Negative edge weights are not allowed")
        graph.setdefault(from_node, []).append((to_node, weight))

    if start == end:
        return 0, [start]

    distances = {start: 0}
    previous = {}
    tie_breaker = count()
    priority_queue = [(0, next(tie_breaker), start)]

    while priority_queue:
        current_distance, _, current_node = heapq.heappop(priority_queue)

        # Ignore outdated queue entries
        if current_distance != distances.get(current_node):
            continue

        if current_node == end:
            break

        for neighbor, weight in graph.get(current_node, []):
            new_distance = current_distance + weight

            if new_distance < distances.get(neighbor, float("inf")):
                distances[neighbor] = new_distance
                previous[neighbor] = current_node
                heapq.heappush(
                    priority_queue,
                    (new_distance, next(tie_breaker), neighbor)
                )

    if end not in distances:
        return None, None

    # Reconstruct the path
    path = []
    node = end
    while node != start:
        path.append(node)
        node = previous[node]
    path.append(start)
    path.reverse()

    return distances[end], path
